use crate::container;
use std::io;
pub const ELF: &[u8]=b"\x7fELF"; pub const SRAM_BASE:u64=0x180000000; pub const DFU_IMAGE_BASE:u64=0x18001c000; pub const CMD_AREA:u64=0x1000;
#[derive(Debug)] pub struct Plan{pub kind:&'static str,pub base:u64,pub entry:Option<u64>,pub segments:Vec<(u64,Vec<u8>)>,pub staged:bool}
impl Plan{pub fn size(&self)->usize{self.segments.iter().map(|x|x.1.len()).sum()} }
fn bad(s:impl Into<String>)->io::Error{io::Error::new(io::ErrorKind::InvalidInput,s.into())}
fn check(base:u64,len:usize,scratch:bool)->io::Result<()> {if len==0||base<SRAM_BASE||base+len as u64>container::SRAM_END{return Err(bad("image is outside the SRAM window"))}if scratch&&(base+len as u64>container::STAGE_BASE||(base<DFU_IMAGE_BASE+CMD_AREA&&base+len as u64>DFU_IMAGE_BASE)){return Err(bad("image overlaps a Goat staging or DFU command window"))}Ok(())}
fn elf(b:&[u8],stage:Option<u64>,entry:Option<u64>)->io::Result<Plan>{if b.len()<64||&b[..4]!=ELF||b[4]!=2||b[5]!=1{return Err(bad("not a 64-bit little-endian ELF"))}let typ=u16::from_le_bytes([b[16],b[17]]);let mach=u16::from_le_bytes([b[18],b[19]]);if typ!=2||mach!=183{return Err(bad("ELF must be AArch64 ET_EXEC"))}let ent=u64::from_le_bytes(b[24..32].try_into().unwrap());let phoff=u64::from_le_bytes(b[32..40].try_into().unwrap()) as usize;let ents=u16::from_le_bytes([b[54],b[55]]) as usize;let count=u16::from_le_bytes([b[56],b[57]]) as usize;let mut seg=Vec::new();for i in 0..count{let o=phoff+i*ents;if o+56>b.len(){return Err(bad("ELF program header outside file"))}let typ=u32::from_le_bytes(b[o..o+4].try_into().unwrap());if typ!=1{continue}let off=u64::from_le_bytes(b[o+8..o+16].try_into().unwrap());let va=u64::from_le_bytes(b[o+16..o+24].try_into().unwrap());let pa=u64::from_le_bytes(b[o+24..o+32].try_into().unwrap());let n=u64::from_le_bytes(b[o+32..o+40].try_into().unwrap());if n==0||off+n>b.len() as u64{continue}seg.push((if pa!=0{pa}else{va},b[off as usize..(off+n) as usize].to_vec()));}if seg.is_empty(){return Err(bad("ELF has no PT_LOAD segments"))}seg.sort_by_key(|x|x.0);let delta=stage.map(|x|x-seg[0].0).unwrap_or(0);let e=ent+delta;if let Some(x)=entry{if x!=e{return Err(bad("--entry disagrees with ELF entry"))}}for (a,d) in &seg{check(a+delta,d.len(),true)?}Ok(Plan{kind:"elf",base:seg[0].0+delta,entry:Some(e),segments:seg.into_iter().map(|(a,d)|(a+delta,d)).collect(),staged:false})}
pub fn plan(b:&[u8],stage:Option<u64>,entry:Option<u64>,key:Option<&[u8]>,stage_container:bool)->io::Result<Plan>{if b.is_empty(){return Err(bad("image is empty"))}if &b[..4.min(b.len())]==ELF{return elf(b,stage,entry)}if b[0]==0x30{if let Ok(c)=container::parse(b){if stage_container{let base=stage.unwrap_or(container::STAGE_BASE);check(base,b.len(),false)?;if !c.verify(){return Err(bad("container signature is invalid"))}return Ok(Plan{kind:"container",base,entry:None,segments:vec![(base,b.to_vec())],staged:true})}if !c.verify(){return Err(bad("container signature is invalid"))}let p=c.decrypt(key.ok_or_else(||bad("container key is required"))?)?;check(c.load_base,p.len(),true)?;let e=c.load_base+c.entry_off;return Ok(Plan{kind:"container",base:c.load_base,entry:Some(e),segments:vec![(c.load_base,p)],staged:false})}}let base=stage.unwrap_or(SRAM_BASE);let e=entry.unwrap_or(base+0x1000);check(base,b.len(),true)?;if e<base||e>=base+b.len() as u64{return Err(bad("entry is outside image"))}Ok(Plan{kind:"raw",base,entry:Some(e),segments:vec![(base,b.to_vec())],staged:false})}
